{"command":"cat > /tmp/test_diff.rs <<'RS'
fn main() {
    let cases = vec![
        ("aaa.txt", "aba.txt"),
        ("abcdef.txt", "aXbcdef.txt"),
        ("aaa.txt", "sameaa.txt"),
        ("hello.txt", "hi.txt"),
        ("a.txt", "longreplacement.txt"),
        ("abc_abc.txt", "X_abc.txt"),
        ("caf\u{e9}.txt", "cafe.txt"),
    ];
    for (a,b) in cases {
        println!("=== {} -> {}", a, b);
        let d = diff::chars(a,b);
        for r in &d {
            match r {
                diff::Result::Left(c) => print!("L({}) ", c),
                diff::Result::Both(l,_r) => print!("B({}) ", l),
                diff::Result::Right(c) => print!("R({}) ", c),
            }
        }
        println!("");
        // group consecutive Both/Right?
        // Simulate coloring: Both green, Right red, Left ignored, group consecutive same?
        let mut segs: Vec<(char, String)> = vec![]; // 'G' or 'R'
        for r in d {
            match r {
                diff::Result::Left(_) => {
                    // split? push marker?
                    // For now, force split by pushing empty?
                    // Actually Left breaks groups, so next Both starts new group even if same color?
                    // We'll insert a break
                    segs.push(('X', String::new()));
                },
                diff::Result::Both(_,r) => {
                    if let Some((c,s)) = segs.last_mut() {
                        if *c=='G' { s.push(r); continue; }
                    }
                    segs.push(('G', r.to_string()));
                },
                diff::Result::Right(c) => {
                    if let Some((cc,s)) = segs.last_mut() {
                        if *cc=='R' { s.push(c); continue; }
                    }
                    segs.push(('R', c.to_string()));
                }
            }
        }
        println!("segs: {:?}", segs);
    }
}
