use clap::{Arg, ArgAction, Command};

fn common_args(cmd: Command) -> Command {
    cmd.arg(Arg::new("dry-run").short('n').long("dry-run").help("Only show what would be done (default mode)").action(ArgAction::SetTrue).conflicts_with("force"))
        .arg(Arg::new("force").short('f').long("force").help("Make actual changes to files").action(ArgAction::SetTrue).conflicts_with("dry-run"))
        .arg(Arg::new("backup").short('b').long("backup").help("Generate file backups before renaming").action(ArgAction::SetTrue))
        .arg(Arg::new("silent").short('s').long("silent").help("Do not print any information").action(ArgAction::SetTrue))
        .arg(Arg::new("color").long("color").value_name("COLOR").help("Set color output mode").default_value("auto").value_parser(["always","never","auto"]))
        .arg(Arg::new("dump").long("dump").help("Force dumping operations into a file even in dry-run mode").action(ArgAction::SetTrue).conflicts_with("no-dump"))
        .arg(Arg::new("dump-prefix").long("dump-prefix").value_name("DUMP_PREFIX").help("Set the dump file prefix").default_value("rnr-").conflicts_with("no-dump"))
        .arg(Arg::new("no-dump").long("no-dump").help("Do not dump operations into a file").action(ArgAction::SetTrue).conflicts_with("dump").conflicts_with("dump-prefix"))
}

fn main() {
    let regex_cmd = common_args(Command::new("regex").about("Rename files and directories using a regular expression").arg_required_else_help(true))
        .arg(Arg::new("replace-limit").short('l').long("replace-limit").value_name("LIMIT").help("Limit of replacements, all matches if set to 0").value_parser(clap::value_parser!(usize)))
        .arg(Arg::new("replace-transform").short('t').long("replace-transform").value_name("REPLACE_TRANSFORM").help("Apply a transformation to replacements including captured groups").value_parser(["upper","lower","ascii"]))
        .arg(Arg::new("include-dirs").short('D').long("include-dirs").help("Rename matching directories").action(ArgAction::SetTrue))
        .arg(Arg::new("recursive").short('r').long("recursive").help("Recursive mode").action(ArgAction::SetTrue))
        .arg(Arg::new("max-depth").short('d').long("max-depth").value_name("LEVEL").help("Set max depth in recursive mode").value_parser(clap::value_parser!(usize)).requires("recursive"))
        .arg(Arg::new("hidden").short('x').long("hidden").help("Include hidden files and directories").action(ArgAction::SetTrue).requires("recursive"))
        .arg(Arg::new("EXPRESSION").help("Expression to match (can be a regex)").required(true))
        .arg(Arg::new("REPLACEMENT").help("Expression replacement (use single quotes for capture groups)").required(true))
        .arg(Arg::new("PATHS").value_name("PATH(S)").help("Target paths").required(true).num_args(1..));
    let from_file_cmd = common_args(Command::new("from-file").about("Read operations from a dump file").arg_required_else_help(true))
        .arg(Arg::new("undo").short('u').long("undo").help("Undo the operations from the dump file").action(ArgAction::SetTrue))
        .arg(Arg::new("DUMPFILE").required(true));
    let to_ascii_cmd = common_args(Command::new("to-ascii").about("Replace file name UTF-8 chars with ASCII chars representation").arg_required_else_help(true))
        .arg(Arg::new("include-dirs").short('D').long("include-dirs").help("Rename matching directories").action(ArgAction::SetTrue))
        .arg(Arg::new("recursive").short('r').long("recursive").help("Recursive mode").action(ArgAction::SetTrue))
