        .arg(Arg::new("hidden").short('x').long("hidden").help("Include hidden files and directories").action(ArgAction::SetTrue).requires("recursive"))
        .arg(Arg::new("PATHS").value_name("PATH(S)").help("Target paths").required(true).num_args(1..));
