fn deunicode(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        if c.is_ascii() {
            out.push(c);
        } else {
            // check special mappings first
            match c {
                'ø' => out.push('o'),
                'Ø' => out.push('O'),
                'œ' => out.push_str("oe"),
                'Œ' => out.push_str("Oe"),
                '€' => out.push_str("EUR"),
                '©' => out.push_str("(C)"),
                '®' => out.push_str("(R)"),
                '™' => out.push_str("TM"),
                'α' => out.push('a'),
                'β' => out.push('v'),
                '中' => out.push_str("Zhong"),
                'あ' => out.push('a'),
                '한' => out.push_str("Han"),
                '😀' => out.push_str(":grinning:"),
                '🚀' => out.push_str(":rocket:"),
                'ﬁ' => out.push_str("fi"),
                'ﬂ' => out.push_str("fl"),
                '‐' | '–' | '—' => out.push('-'),
                '“' | '”' => out.push('"'),
                '‘' | '’' => out.push('\''),
                '…' => out.push_str("..."),
                '。' => out.push('.'),
                '、' => out.push(','),
                '\u{3000}' => out.push(' '),
                '\u{200b}' => {},
                '\u{00a0}' => out.push(' '),
                '⁄' | '∕' | '／' | '╱' => out.push('/'),
                '＼' | '⧵' | '﹨' | '∖' | '╲' => out.push('\\'),
                '⸮' | '�' => out.push('?'),
                _ => {
                    let m = deunicode_char(c);
                    if m.is_empty() {
                        // fallback: try to strip diacritics? For unknown, use ? or empty?
                        // For combining marks, empty
                        if ('\u{0300}'..='\u{036f}').contains(&c) {
                            // skip
                        } else {
                            // unknown: skip? or push ?
                            // Let's push empty for now, but for CJK etc need mapping
                            // Fallback to empty
                        }
                    } else {
                        out.push_str(m);
                    }
                }
            }
        }
    }
    out
}

