                            eprint!("\x1b[31mError: \x1b[0m");
                            eprint!("Cannot rename ");
                            eprintln!("\x1b[31m{} -> {}\n{}\x1b[0m", op.source, op.target, e);
                        } else {
                            eprintln!("Error: Cannot rename {} -> {}", op.source, op.target);
                            eprintln!("{}", e);
                        }
                    }
                    had_error = true;
                    break;
                }
            }
        }
        if had_error { std::process::exit(1); }
    }
}

fn handle_from_file(sub: &clap::ArgMatches) {
    let silent = sub.get_flag("silent");
    let use_color = is_color_enabled(sub);
    let force = sub.get_flag("force");
    let is_dry = !force;
    let backup = sub.get_flag("backup");
    let dump_flag = sub.get_flag("dump");
    let no_dump = sub.get_flag("no-dump");
    let dump_prefix = sub.get_one::<String>("dump-prefix").unwrap().clone();
    let dumpfile = sub.get_one::<String>("DUMPFILE").unwrap().clone();
    let undo = sub.get_flag("undo");

    // try to read file
    let content = match fs::read_to_string(&dumpfile) {
        Ok(c) => c,
        Err(_) => {
            if is_dry {
                print_dry_run(use_color, silent);
            }
            if !silent {
                if use_color {
                    eprint!("\x1b[31mError: \x1b[0m");
                    eprint!("Cannot open/read file ");
                    eprintln!("\x1b[31m{}\x1b[0m", dumpfile);
                } else {
                    eprintln!("Error: Cannot open/read file {}", dumpfile);
                }
            }
            std::process::exit(1);
        }
    };
    let parsed: Result<DumpFile, _> = serde_json::from_str(&content);
    let dump: DumpFile = match parsed {
        Ok(d) => {
            // need to validate? serde will fail if missing fields, but need to ensure date present? Already required.
            d
        },
        Err(_) => {
            if is_dry {
                print_dry_run(use_color, silent);
            }
            if !silent {
                if use_color {
                    eprint!("\x1b[31mError: \x1b[0m");
                    eprint!("Cannot parse JSON file ");
                    eprintln!("\x1b[31m{}\x1b[0m", dumpfile);
                } else {
                    eprintln!("Error: Cannot parse JSON file {}", dumpfile);
                }
            }
            std::process::exit(1);
        }
    };
    // Also need to handle case where file is directory? read_to_string on dir fails with IsADirectory, which goes to open/read error, but original gives parse error for dir? Let's check: earlier from-file with dir gave parse error, not open/read. Our code gives open/read for dir (since read_to_string fails). Need to handle: if path is dir, read_to_string fails, but original says parse error. How to distinguish? Original tries to open/read, if fails due to IsADirectory? Actually reading a directory as file fails, but they report parse error, not open/read. That suggests they first check if file can be opened, then try to parse, and for dir, open succeeds? Or they use different logic: open file succeeds for dir? On Linux, opening a dir for reading as file succeeds, but reading fails? Hmm.
    // Let's check: our read_to_string on dir: what error? It returns Err with "Is a directory". Original for dir gave "Cannot parse JSON", not "Cannot open/read". So they must have opened successfully, then failed to parse.
    // How to replicate? We should try fs::File::open first: if open fails -> open/read error. If open succeeds but read fails or parse fails -> parse error.
    // For dir, File::open succeeds (opening dir succeeds), but read_to_string fails? Actually File::open on dir succeeds, but read fails. So we need to separate.
    // Let's implement: match File::open, if Err -> open/read, else read to string, if Err -> parse error, else parse json, if Err -> parse error.
    // But our current code treats read failure as open/read. Need to fix.

    let mut ops: Vec<Operation> = if undo {
        let mut rev: Vec<Operation> = dump.operations.iter().map(|o| Operation { source: o.target.clone(), target: o.source.clone() }).collect();
        rev.reverse();
        rev
    } else {
        dump.operations
    };

    // dump?
    let should_dump = !no_dump && (force || dump_flag);
    if should_dump {
        let now = chrono::Local::now();
        let date_str = now.format("%Y-%m-%d %H:%M:%S").to_string();
        let file_date = now.format("%Y-%m-%d_%H%M%S").to_string();
        let filename = format!("{}{}.json", dump_prefix, file_date);
        let new_dump = DumpFile { date: date_str, operations: ops.clone() };
        let content = serde_json::to_string_pretty(&new_dump).unwrap();
        match fs::write(&filename, content) {
            Ok(_) => {},
            Err(_) => {
                if !silent {
                    if use_color {
                        eprint!("\x1b[31mError: \x1b[0m");
                        eprint!("Cannot create file ");
                        eprintln!("\x1b[31m{}\x1b[0m", filename);
                    } else {
                        eprintln!("Error: Cannot create file {}", filename);
                    }
                }
                std::process::exit(1);
            }
        }
    }

    if is_dry {
        print_dry_run(use_color, silent);
        if silent { return; }
        for op in &ops {
            println!("{}", color_mapping(&op.source, &op.target, use_color));
        }
    } else {
        let mut had_error = false;
        for op in &ops {
            if backup {
                let is_dir = match fs::metadata(&op.source) {
                    Ok(md) => md.is_dir(),
                    Err(_) => false,
                };
                if !is_dir {
                    let mut bk = format!("{}.bk", op.source);
                    if fs::symlink_metadata(&bk).is_ok() {
                        let mut i = 1;
                        loop {
                            let cand = format!("{}.bk.{}", op.source, i);
                            if fs::symlink_metadata(&cand).is_err() { bk = cand; break; }
                            i += 1;
                        }
                    }
                    match fs::copy(&op.source, &bk) {
                        Ok(_) => {
                            if !silent {
                                if use_color {
                                    println!("\x1b[1mInfo: \x1b[0m Backup created - \x1b[38;5;8m{} -> {}\x1b[0m", op.source, bk);
                                } else {
                                    println!("Info:  Backup created - {} -> {}", op.source, bk);
                                }
                            }
                        },
                        Err(_) => {
                            if !silent {
                                if use_color {
                                    eprint!("\x1b[31mError: \x1b[0m");
                                    eprint!("Cannot create a backup of ");
                                    eprintln!("\x1b[31m{}\x1b[0m", op.source);
                                } else {
                                    eprintln!("Error: Cannot create a backup of {}", op.source);
                                }
                            }
                            had_error = true;
                            break;
                        }
                    }
                }
            }
            match fs::rename(&op.source, &op.target) {
                Ok(_) => {
                    if !silent {
                        println!("{}", color_mapping(&op.source, &op.target, use_color));
                    }
                },
                Err(e) => {
                    if !silent {
                        if use_color {
                            eprint!("\x1b[31mError: \x1b[0m");
                            eprint!("Cannot rename ");
                            eprintln!("\x1b[31m{} -> {}\n{}\x1b[0m", op.source, op.target, e);
                        } else {
                            eprintln!("Error: Cannot rename {} -> {}", op.source, op.target);
                            eprintln!("{}", e);
                        }
                    }
                    had_error = true;
                    break;
                }
            }
        }
        if had_error { std::process::exit(1); }
    }
}
