fn strip_trailing_slash(p: &str) -> String {
    if p.len() > 1 {
        let t = p.trim_end_matches('/');
        if t.is_empty() { "/".to_string() } else { t.to_string() }
    } else { p.to_string() }
}

fn depth_of(p: &str) -> usize {
    p.matches('/').count()
}

fn split_parent_filename(p: &str) -> (String, String) {
    if let Some(pos) = p.rfind('/') {
        (p[..=pos].to_string(), p[pos+1..].to_string())
    } else {
        ("".to_string(), p.to_string())
    }
}

fn is_hidden_name(name: &str) -> bool {
    name.starts_with('.') && name != "." && name != ".."
}

fn collect_candidates(paths: Vec<String>, recursive: bool, include_dirs: bool, max_depth: Option<usize>, hidden: bool) -> Vec<String> {
    let mut set: HashSet<String> = HashSet::new();
    let mut out: Vec<String> = Vec::new();
    for raw in paths {
        let stripped = strip_trailing_slash(&raw);
        // check existence via symlink_metadata
        if fs::symlink_metadata(&stripped).is_err() {
            continue;
        }
        if !recursive {
            // direct
            let is_dir = match fs::metadata(&stripped) {
                Ok(md) => md.is_dir(),
                Err(_) => false,
            };
            if is_dir {
                if include_dirs {
                    if set.insert(stripped.clone()) { out.push(stripped); }
                }
            } else {
                if set.insert(stripped.clone()) { out.push(stripped); }
            }
        } else {
            // recursive: check if root is file (not dir)
            let is_dir = match fs::metadata(&stripped) {
                Ok(md) => md.is_dir(),
                Err(_) => false,
            };
            if !is_dir {
                // file root: single candidate (ignore max_depth, hidden for root)
                if set.insert(stripped.clone()) { out.push(stripped); }
                continue;
            }
            // dir root: walk
            let mut builder = walkdir::WalkDir::new(&stripped).follow_links(false);
            if let Some(d) = max_depth {
                builder = builder.max_depth(d);
            }
            // need to handle hidden filtering manually
            let walker = builder.into_iter().filter_entry(|e| {
                if e.depth() == 0 { return true; }
                if hidden { return true; }
                if let Some(name) = e.file_name().to_str() {
                    if is_hidden_name(name) { return false; }
                } else {
                    // non-utf8? check bytes?
                    let lossy = e.file_name().to_string_lossy();
                    if is_hidden_name(&lossy) { return false; }
                }
                true
            });
            for entry in walker {
                let entry = match entry {
                    Ok(en) => en,
                    Err(_) => continue,
                };
                let path = entry.path().to_string_lossy().to_string();
                // Normalize? walkdir already gives normalized
                // For root itself (depth 0), handle include_dirs
                if entry.depth() == 0 {
                    if include_dirs {
                        // root dir itself: check if should be candidate? It will be considered for rename if matches.
                        // But need to use stripped version? walkdir gives stripped? For root "./", walkdir gives "./" vs "."? Use stripped?
                        // Use stripped for root to match original (stripped trailing slash)
                        let src = stripped.clone();
                        if set.insert(src.clone()) { out.push(src); }
                    }
                    continue;
                }
                // For others, determine file vs dir via metadata (follow)
                let is_entry_dir = match fs::metadata(entry.path()) {
                    Ok(md) => md.is_dir(),
                    Err(_) => {
                        // Check if symlink? If symlink_metadata says symlink, treat as file (for broken) unless symlink to dir?
                        // For broken, metadata fails, treat as file
                        // For other errors, skip? But broken should be included as file
                        // Check symlink_metadata to see if exists
                        match fs::symlink_metadata(entry.path()) {
                            Ok(md) => {
                                if md.file_type().is_symlink() {
                                    // broken symlink -> file
                                    false
                                } else {
                                    // other? treat as file?
                                    false
                                }
                            },
                            Err(_) => continue,
                        }
                    }
                };
                if is_entry_dir {
                    if include_dirs {
                        if set.insert(path.clone()) { out.push(path); }
                    }
                } else {
                    if set.insert(path.clone()) { out.push(path); }
                }
            }
        }
    }
    out
}

fn print_dry_run(color: bool, silent: bool) {
    if silent { return; }
    if color {
        println!("\x1b[1mThis is a DRY-RUN\x1b[0m");
    } else {
        println!("This is a DRY-RUN");
    }
}

fn color_mapping(source: &str, target: &str, use_color: bool) -> String {
    if !use_color {
        return format!("{} -> {}", source, target);
    }
    let (s_parent, s_file) = split_parent_filename(source);
    let (t_parent, t_file) = split_parent_filename(target);
    // source grey, target parent green, target file diff
    let mut out = String::new();
    if !s_parent.is_empty() {
        out.push_str(&format!("\x1b[38;5;8m{}\x1b[0m", s_parent));
    }
    out.push_str(&format!("\x1b[38;5;8m{}\x1b[0m", s_file));
    out.push_str(" -> ");
    if !t_parent.is_empty() {
        out.push_str(&format!("\x1b[32m{}\x1b[0m", t_parent));
    }
    // diff old filename vs new filename
    let diffs = diff::chars(&s_file, &t_file);
    // group consecutive Both/Right, ignoring Left (which breaks groups)
    // We need to produce segments: Both -> green, Right -> red, Left breaks (splits groups)
    // Implementation: iterate, accumulate current segment type, flush on type change or Left
    let mut segs: Vec<(char, String)> = Vec::new();
    for d in diffs {
        match d {
            diff::Result::Left(_) => {
                // break: force new segment even if same color next? Mark break by pushing sentinel
                segs.push(('X', String::new()));
            },
            diff::Result::Both(_, c) => {
                // if last is G and previous not break, append, else new
                if let Some((t, s)) = segs.last_mut() {
                    if *t == 'G' {
                        s.push(c);
                        continue;
                    }
                }
                segs.push(('G', c.to_string()));
            },
            diff::Result::Right(c) => {
                if let Some((t, s)) = segs.last_mut() {
                    if *t == 'R' {
                        s.push(c);
                        continue;
                    }
                }
                segs.push(('R', c.to_string()));
            }
        }
    }
    for (t, s) in segs {
        if t == 'X' || s.is_empty() { continue; }
        if t == 'G' {
            out.push_str(&format!("\x1b[32m{}\x1b[0m", s));
        } else if t == 'R' {
            out.push_str(&format!("\x1b[1;31m{}\x1b[0m", s));
        }
    }
    out
}

fn print_error(msg: &str, detail_red: Option<&str>, use_color: bool, silent: bool, is_bad_expression: bool) {
    if silent && !is_bad_expression { return; }
    if use_color {
        eprint!("\x1b[31mError: \x1b[0m");
        // msg is like "Bad expression provided" or "Conflict with existing path " etc.
        // For bad expression, msg contains rest? Handle separately
        eprint!("{}", msg);
        if let Some(d) = detail_red {
            eprint!("\x1b[31m{}\x1b[0m", d);
        }
        eprintln!();
    } else {
        eprint!("Error: ");
        eprint!("{}", msg);
        if let Some(d) = detail_red {
            eprint!("{}", d);
        }
        eprintln!();
    }
}

fn handle_regex(sub: &clap::ArgMatches) {
    let silent = sub.get_flag("silent");
    let use_color = is_color_enabled(sub);
    let force = sub.get_flag("force");
    let is_dry = !force;
    let backup = sub.get_flag("backup");
    let dump_flag = sub.get_flag("dump");
    let no_dump = sub.get_flag("no-dump");
    let dump_prefix = sub.get_one::<String>("dump-prefix").unwrap().clone();
    let expression = sub.get_one::<String>("EXPRESSION").unwrap().clone();
    let replacement = sub.get_one::<String>("REPLACEMENT").unwrap().clone();
    let paths: Vec<String> = sub.get_many::<String>("PATHS").unwrap().cloned().collect();
    let replace_limit: Option<usize> = sub.get_one::<usize>("replace-limit").copied();
    let replace_transform: Option<String> = sub.get_one::<String>("replace-transform").cloned();
    let include_dirs = sub.get_flag("include-dirs");
    let recursive = sub.get_flag("recursive");
    let max_depth: Option<usize> = sub.get_one::<usize>("max-depth").copied();
    let hidden = sub.get_flag("hidden");

    // compile regex
    let re = match Regex::new(&expression) {
        Ok(r) => r,
        Err(e) => {
            // print error, ignore silent
            if use_color {
                eprint!("\x1b[31mError: \x1b[0m");
                eprintln!("Bad expression provided");
                eprintln!();
                eprintln!("\x1b[31m{}\x1b[0m", e);
            } else {
                eprintln!("Error: Bad expression provided");
                eprintln!();
                eprintln!("{}", e);
            }
            std::process::exit(1);
        }
    };

    let candidates = collect_candidates(paths, recursive, include_dirs, max_depth, hidden);
    // apply regex to each
    let mut ops: Vec<Operation> = Vec::new();
    let limit = replace_limit.unwrap_or(1);
    for src in candidates {
        let (parent, filename) = split_parent_filename(&src);
        let new_filename = if let Some(ref t) = replace_transform {
            if t == "upper" {
                if limit == 0 {
                    re.replace_all(&filename, |caps: &regex::Captures| {
                        let mut buf = String::new();
                        caps.expand(&replacement, &mut buf);
                        buf.to_uppercase()
                    }).to_string()
                } else {
                    re.replacen(&filename, limit, |caps: &regex::Captures| {
                        let mut buf = String::new();
                        caps.expand(&replacement, &mut buf);
                        buf.to_uppercase()
                    }).to_string()
                }
            } else if t == "lower" {
                if limit == 0 {
                    re.replace_all(&filename, |caps: &regex::Captures| {
                        let mut buf = String::new();
                        caps.expand(&replacement, &mut buf);
                        buf.to_lowercase()
                    }).to_string()
                } else {
                    re.replacen(&filename, limit, |caps: &regex::Captures| {
                        let mut buf = String::new();
                        caps.expand(&replacement, &mut buf);
                        buf.to_lowercase()
                    }).to_string()
                }
            } else { // ascii
                if limit == 0 {
                    re.replace_all(&filename, |caps: &regex::Captures| {
                        let mut buf = String::new();
                        caps.expand(&replacement, &mut buf);
                        deunicode(&buf).replace('/', "_")
                    }).to_string()
                } else {
                    re.replacen(&filename, limit, |caps: &regex::Captures| {
                        let mut buf = String::new();
                        caps.expand(&replacement, &mut buf);
                        deunicode(&buf).replace('/', "_")
                    }).to_string()
                }
            }
        } else {
            if limit == 0 {
                re.replace_all(&filename, &replacement).to_string()
            } else {
                re.replacen(&filename, limit, &replacement).to_string()
            }
        };
        if new_filename == filename { continue; }
        let target = format!("{}{}", parent, new_filename);
        ops.push(Operation { source: src, target });
    }

    // sort by depth desc, then source asc for determinism
    ops.sort_by(|a,b| {
        let da = depth_of(&a.source);
        let db = depth_of(&b.source);
        db.cmp(&da).then_with(|| a.source.cmp(&b.source))
    });

    // validation: same-name
    {
        let mut map: HashMap<String, Vec<usize>> = HashMap::new();
        for (i, op) in ops.iter().enumerate() {
            map.entry(op.target.clone()).or_default().push(i);
        }
        let mut dup_groups: Vec<(String, Vec<Operation>)> = Vec::new();
        for (tgt, idxs) in map {
            if idxs.len() > 1 {
                let mut group: Vec<Operation> = idxs.iter().map(|&i| ops[i].clone()).collect();
                group.sort_by(|a,b| a.source.cmp(&b.source));
                dup_groups.push((tgt, group));
            }
        }
        if !dup_groups.is_empty() {
            dup_groups.sort_by(|a,b| a.0.cmp(&b.0));
            if is_dry {
                print_dry_run(use_color, silent);
            }
            if !silent {
                if use_color {
                    eprint!("\x1b[31mError: \x1b[0m");
                    eprintln!("Files will have the same name");
                    // For color, need double-wrapped reds as observed
                    // Structure: \n\x1b[31m\x1b[31m\n + groups + \x1b[0m\x1b[0m\n ?
                    // Actually observed: after first line, line2 is \x1b[31m\x1b[31m, then mappings, middle \x1b[0m\x1b[31m, end \x1b[0m\x1b[0m
                    // Implement: eprint \x1b[31m\x1b[31m\n, then for each group idx, for each j in 1..len, print first + j, with separators
                    eprintln!("\x1b[31m\x1b[31m");
                    let mut first_group = true;
                    for (_tgt, group) in &dup_groups {
                        for j in 1..group.len() {
                            if !first_group {
                                eprintln!("\x1b[0m\x1b[31m");
                            }
                            first_group = false;
                            eprintln!("{}->{}", group[0].source, group[0].target);
                            eprintln!("{}->{}", group[j].source, group[j].target);
                        }
                    }
                    eprintln!("\x1b[0m\x1b[0m");
                } else {
                    eprintln!("Error: Files will have the same name");
                    eprintln!();
                    for (_tgt, group) in &dup_groups {
                        for j in 1..group.len() {
                            eprintln!("{}->{}", group[0].source, group[0].target);
                            eprintln!("{}->{}", group[j].source, group[j].target);
                            eprintln!();
                        }
                    }
                }
            }
            std::process::exit(1);
        }
    }
    // validation: existing
    for op in &ops {
        if fs::symlink_metadata(&op.target).is_ok() {
            if is_dry {
                print_dry_run(use_color, silent);
            }
            if !silent {
                if use_color {
                    eprint!("\x1b[31mError: \x1b[0m");
                    eprint!("Conflict with existing path ");
                    eprintln!("\x1b[31m{} -> {}\x1b[0m", op.source, op.target);
                } else {
                    eprintln!("Error: Conflict with existing path {} -> {}", op.source, op.target);
                }
            }
            std::process::exit(1);
        }
    }

    // dump?
    let should_dump = !no_dump && (force || dump_flag);
    if should_dump {
        let now = chrono::Local::now();
        let date_str = now.format("%Y-%m-%d %H:%M:%S").to_string();
        let file_date = now.format("%Y-%m-%d_%H%M%S").to_string();
        let filename = format!("{}{}.json", dump_prefix, file_date);
        let dump = DumpFile { date: date_str, operations: ops.clone() };
        let content = serde_json::to_string_pretty(&dump).unwrap();
        match fs::write(&filename, content) {
            Ok(_) => {},
            Err(_) => {
                if !silent {
                    if use_color {
                        eprint!("\x1b[31mError: \x1b[0m");
                        eprint!("Cannot create file ");
                        eprintln!("\x1b[31m{}\x1b[0m", filename);
                    } else {
                        eprintln!("Error: Cannot create file {}", filename);
                    }
                }
                std::process::exit(1);
            }
        }
    }

    if is_dry {
        print_dry_run(use_color, silent);
        if silent { return; }
        for op in &ops {
            println!("{}", color_mapping(&op.source, &op.target, use_color));
        }
    } else {
        // force: execute
        let mut had_error = false;
        for op in &ops {
            // backup?
            if backup {
                // check if dir? skip backup for dirs
                let is_dir = match fs::metadata(&op.source) {
                    Ok(md) => md.is_dir(),
                    Err(_) => false,
                };
                if !is_dir {
                    // find backup path
                    let mut bk = format!("{}.bk", op.source);
                    if fs::symlink_metadata(&bk).is_ok() {
                        let mut i = 1;
                        loop {
                            let cand = format!("{}.bk.{}", op.source, i);
                            if fs::symlink_metadata(&cand).is_err() { bk = cand; break; }
                            i += 1;
                        }
                    }
                    match fs::copy(&op.source, &bk) {
                        Ok(_) => {
                            if !silent {
                                if use_color {
                                    println!("\x1b[1mInfo: \x1b[0m Backup created - \x1b[38;5;8m{} -> {}\x1b[0m", op.source, bk);
                                } else {
                                    println!("Info:  Backup created - {} -> {}", op.source, bk);
                                }
                            }
                        },
                        Err(_) => {
                            if !silent {
                                if use_color {
                                    eprint!("\x1b[31mError: \x1b[0m");
                                    eprint!("Cannot create a backup of ");
                                    eprintln!("\x1b[31m{}\x1b[0m", op.source);
                                } else {
                                    eprintln!("Error: Cannot create a backup of {}", op.source);
                                }
                            }
                            had_error = true;
                            break;
                        }
                    }
                }
            }
            match fs::rename(&op.source, &op.target) {
                Ok(_) => {
                    if !silent {
                        println!("{}", color_mapping(&op.source, &op.target, use_color));
                    }
                },
                Err(e) => {
                    if !silent {
                        if use_color {
                            eprint!("\x1b[31mError: \x1b[0m");
                            eprint!("Cannot rename ");
                            eprintln!("\x1b[31m{} -> {}\n{}\x1b[0m", op.source, op.target, e);
                        } else {
                            eprintln!("Error: Cannot rename {} -> {}", op.source, op.target);
                            eprintln!("{}", e);
                        }
                    }
                    had_error = true;
                    break;
                }
            }
        }
        if had_error {
            std::process::exit(1);
        }
    }
}

