use std::cmp::max;
fn diff_custom(left: &[char], right: &[char], prefer_left: bool) -> Vec<String> {
    // Simplified LCS table without leading/trailing opt, just full
    let n = left.len(); let m = right.len();
    let mut table = vec![vec![0; m+1]; n+1];
    for i in 0..n {
        for j in 0..m {
            if left[i]==right[j] { table[i+1][j+1]=table[i][j]+1; }
            else { table[i+1][j+1]=max(table[i][j+1], table[i+1][j]); }
        }
    }
    let mut i=n; let mut j=m;
    let mut res: Vec<String>=vec![];
    while i>0 || j>0 {
        if i>0 && j>0 && left[i-1]==right[j-1] {
            res.push(format!("B({})", left[i-1]));
            i-=1; j-=1;
        } else if prefer_left {
            // prefer Left (i-1) when tie?
            if j>0 && (i==0 || table[i][j-1]>=table[i-1][j]) {
                res.push(format!("R({})", right[j-1])); j-=1;
            } else {
                res.push(format!("L({})", left[i-1])); i-=1;
            }
        } else {
            if i>0 && (j==0 || table[i-1][j]>=table[i][j-1]) {
                res.push(format!("L({})", left[i-1])); i-=1;
            } else {
                res.push(format!("R({})", right[j-1])); j-=1;
            }
        }
    }
    res.reverse();
    res
}
fn main() {
    let cases = vec![("aaa.txt","aba.txt"), ("aaaa.txt","abaa.txt"), ("a.txt","longreplacement.txt")];
    for (a,b) in cases {
        let l: Vec<char>=a.chars().collect(); let r: Vec<char>=b.chars().collect();
        println!("=== {} -> {}", a,b);
        println!("prefer Right (diff crate order): {:?}", diff_custom(&l,&r,false));
        println!("prefer Left: {:?}", diff_custom(&l,&r,true));
    }
}
